INSERT INTO books (id, title, author, publisher, isbn, cover_url, description, status, created_at) VALUES (1, '이방인', '알베르 카뮈', '문예출판사', '9788931025118', 'https://books.google.com/books/content?id=u--cEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '《이방인》은 실존주의의 문학적 승리, 나아가 부조리에 대한 깊은 통찰과 신랄한 고발로 격찬받는 카뮈의 대표작이다. 카뮈가 노벨문학상을 받는 데 결정적 기여를 한 작품이기도 하다. 카뮈에게 부조리는 이성을 가진 자가 마주할 수밖에 없는 비극적 운명에 관한 것이다. 이성을 가진 인간은 세계를 이해하고자 하는 합리적 욕망을 품는다. 그런데 세계는 인간이 알아야 할 만한 별다른 뜻이 없다. 그러니까, 인간의 욕망은 합리적인데 세계는 불합리하다. 부조리는 바로 이러한 이율배반에서 생기는 모순을 가리키는 말이다. 인간이 피하지 못하는 숙명, 인간의 조건인 셈이다. 《이방인》은 2차 세계대전으로 온 유럽이 사회적, 정신적으로 극심한 혼란기를 보내던 시기인 1942년에 출간되었다. 인간의 본질은 무엇이며 어떠한 토대 위에 서 있는지를 근본적으로 탐구한 카뮈의 문학 작업은 실존주의 사상과 합을 이루어 혼란에 빠진 사람들에게 새로운 인식의 틀을 제공했다. 카뮈가 1957년에 노벨문학상을 받은 것도 전후 황량한 폐허에서 인간 정신의 위기를 간파하고 부조리를 통해 그 극복을 모색했기 때문이었다. 《이방인》은 종종 《시지프 신화》와 함께 통속적 허무주의의 작품으로 읽히기도 하지만 이는 오해다. 카뮈는 오히려 인간의 너절한 현실을 누구보다 적확하게 간파하여 역설적으로 인간의 존엄을 모색한 작가였다. 이제는 신화가 된, 부조리에 대한 불멸의 고발인 《이방인》은 우리를 절망이 아닌 희망으로 이끈다.', 'READING', '2026-09-22 04:14:57.602299');
